      const scaleX = rect.width / baseCanvas.width;
      const scaleY = rect.height / baseCanvas.height;
      const dx = (clientX - rect.left) / scaleX;
      const dy = (clientY - rect.top) / scaleY;
      const x = Math.floor(dx);
      const y = Math.floor(dy);
